/* Rule-based Nynorsk writing support. Own rules, no external text submission. */
const WritingEngine=(()=>{
 const SRC={norm:'https://ordbokene.no/',grammar:'https://sprakradet.no/',style:'https://sprakradet.no/godt-og-korrekt-sprak/praktisk-sprakbruk/nynorskhjelp/substantivtunge-setningar/'};
 const SIMPLE={jeg:['eg'],ikke:['ikkje'],hun:['ho'],hva:['kva'],hvem:['kven'],hvordan:['korleis'],hvorfor:['kvifor'],noe:['noko'],mye:['mykje'],sammen:['saman'],uten:['utan'],allerede:['allereie'],fremdeles:['framleis'],gjøre:['gjere'],være:['vere'],ble:['blei','vart'],bedre:['betre'],skrevet:['skrive'],oppgave:['oppgåve'],oppgaver:['oppgåver'],vanlig:['vanleg'],vanskelig:['vanskeleg'],mulig:['mogleg'],mulighet:['moglegheit','høve'],muligheter:['moglegheiter','høve'],tydelig:['tydeleg'],naturlig:['naturleg'],personlig:['personleg'],skriftlig:['skriftleg'],muntlig:['munnleg'],faglig:['fagleg'],særlig:['særleg'],virkelig:['verkeleg'],egentlig:['eigentleg'],hemmelig:['hemmeleg'],hemmelighet:['løyndom','hemmelegheit'],kjærlighet:['kjærleik'],frihet:['fridom'],trygghet:['tryggleik'],følelse:['kjensle'],følelser:['kjensler'],fortelling:['forteljing'],fortellinger:['forteljingar'],løsning:['løysing'],løsninger:['løysingar'],hovedperson:['hovudperson'],hovedsak:['hovudsak'],øyeblikk:['augneblink'],uke:['veke'],uker:['veker'],måned:['månad'],måneder:['månader'],høst:['haust'],hjerte:['hjarte'],hode:['hovud'],vann:['vatn'],hverandre:['kvarandre'],selv:['sjølv'],flere:['fleire'],mer:['meir'],hjemme:['heime'],hjem:['heim'],begynte:['byrja','begynte'],spørsmålene:['spørsmåla']};
 // Do not flag accepted Nynorsk forms, including «begynte», «skole», «komme», «nå», «også».
 delete SIMPLE.begynte;
 Object.assign(SIMPLE,{gikk:['gjekk'],fikk:['fekk'],spurte:['spurde'],sto:['stod']});
 delete SIMPLE.vann; // «vann» is also the valid Nynorsk past tense of «vinne».
 const escapeRe=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const bounds=s=>new RegExp(`(?<![\\p{L}\\p{M}])(?:${s})(?![\\p{L}\\p{M}])`,'giu');
 const words=s=>[...s.matchAll(/[\p{L}\p{M}]+(?:[-’'][\p{L}\p{M}]+)*/gu)];
 function quoteRanges(text){let ranges=[],start=-1,closer='';const ends={'«':'»','“':'”','"':'"'};for(let i=0;i<text.length;i++){const c=text[i];if(start<0&&ends[c]){start=i;closer=ends[c]}else if(start>=0&&c===closer){ranges.push([start,i+1]);start=-1}}if(start>=0)ranges.push([start,text.length]);return ranges}
 function matchCase(original,replacement){if(original===original.toLocaleUpperCase('nn')&&original!==original.toLocaleLowerCase('nn'))return replacement.toLocaleUpperCase('nn');return /^\p{Lu}/u.test(original)?replacement[0].toLocaleUpperCase('nn')+replacement.slice(1):replacement}
 function analyze(text,{ignoreQuotes=true,genre='general'}={}){
  const quotes=ignoreQuotes?quoteRanges(text):[],issues=[],tokens=words(text);
  const intersects=(start,end)=>quotes.some(([a,b])=>start<b&&end>a);
  function add(start,end,category,title,message,replacements=[],rule='generic',source=SRC[category]||SRC.grammar){if(intersects(start,end))return;const original=text.slice(start,end);issues.push({id:`${rule}:${start}:${end}`,rule,start,end,original,category,title,message,replacements:[...new Set(replacements.map(r=>matchCase(original,r)))],source})}
  function pattern(regex,category,title,message,replace,rule){for(const m of text.matchAll(regex)){const replacements=replace?replace(m):[];add(m.index,m.index+m[0].length,category,title,typeof message==='function'?message(m):message,replacements,rule)}}
  for(const token of tokens){const key=token[0].toLocaleLowerCase('nn');if(SIMPLE[key])add(token.index,token.index+token[0].length,'norm',`Sjå på «${token[0]}»`,'Dette er ei vanleg bokmålsform. Vel ei nynorskform som passar tydinga. Slå opp dersom ordet er eit namn, faguttrykk eller har ei anna tyding.',SIMPLE[key],'bm-'+key)}
  const contextual={noen:['nokon','nokre'],deres:['dykkar','deira'],hvilken:['kva for ein','kva for ei'],hvilket:['kva for eit'],hvilke:['kva for nokre'],hvor:['kvar','kor']};
  for(const token of tokens){const key=token[0].toLowerCase();if(contextual[key])add(token.index,token.index+token[0].length,'grammar',`Vel rett form for «${token[0]}»`,key==='noen'?'Nokre passar ofte i stadfestande fleirtal: nokre bøker. Nokon er vanleg i spørsmål og nekting. Vurder òg kjønn og tal.':key==='deres'?'Dykkar viser til dei du snakkar til; deira viser til andre. Dokkar er òg ei godkjend form.':key==='hvor'?'Kvar spør etter ein stad. Kor blir mellom anna brukt i kor stor og kor langt.':'Uttrykket må passe til kjønnet og talet på substantivet.',contextual[key],'context-'+key)}
  const present={vet:'veit',sier:'seier',skriver:'skriv',leser:'les',finner:'finn',kommer:'kjem',drikker:'drikk',sover:'søv',springer:'spring',sitter:'sit',ligger:'ligg',spiser:'et'};
  // «spiser» can be inflected from accepted «spise»; do not force one lexical choice.
  delete present.spiser;
  pattern(bounds(`(eg|du|han|ho|vi|me|de|dei)\\s+(${Object.keys(present).join('|')})`),'grammar','Sjekk verbet i presens','Her står verbet etter eit personleg pronomen. Sjekk nynorskforma: til dømes skriv, veit eller seier. Nokre verb har uregelrette former.',m=>[m[1]+' '+present[m[2].toLowerCase()]],'strong-present');
  pattern(bounds('(vet|sier)\\s+(eg|du|han|ho|vi|me|de|dei)'),'grammar','Sjekk presensforma','Etter eit innleiande ledd eller i spørsmål kan verbet stå før subjektet. Nynorskformene er veit og seier.',m=>[({vet:'veit',sier:'seier'}[m[1].toLowerCase()])+' '+m[2]],'common-inverted');
  const perfect={skreiv:'skrive',las:'lese',fann:'funne',drakk:'drukke',gjekk:'gått',såg:'sett',var:'vore',kom:'kome',tok:'teke',åt:'ete',sov:'sove',sprang:'sprunge'};
  pattern(bounds(`(har|hadde)\\s+(${Object.keys(perfect).join('|')})`),'grammar','Etter «har» eller «hadde» treng du partisipp','Preteritum og perfektum partisipp er ulike former. Til dømes: eg skreiv, men eg har skrive.',m=>(m[2].toLowerCase()==='tok'?['teke','tatt']:m[2].toLowerCase()==='kom'?['kome','komme']:[perfect[m[2].toLowerCase()]]).map(f=>m[1]+' '+f),'perfect-form');
  pattern(bounds('(kan|skal|vil|må|bør)\\s+å\\s+(skrive|lese|gå|kome|komme|gjere|vere|finne|lære|spele)'),'grammar','Infinitiv utan «å» etter modalverb','Etter kan, skal, vil, må og bør bruker vi vanlegvis infinitiv utan infinitivsmerket å.',m=>[m[1]+' '+m[2]],'modal');
  pattern(bounds('(likar|liker|prøver|ønskjer|ønsker)\\s+og\\s+(lese|skrive|lære|finne|kome|komme|spele)'),'grammar','Undersøk «og» eller «å»','Her ser det ut til at det neste verbet står i infinitiv. Då passar å. Og bind saman jamstilte ord eller ledd.',m=>[m[1]+' å '+m[2]],'og-aa');
  pattern(bounds('(at|fordi|dersom)\\s+(eg|du|han|ho|vi|me|dei)\\s+(kan|skal|vil|har|er)\\s+ikkje'),'grammar','Ordstilling i leddsetninga','I denne typen leddsetning står ikkje vanlegvis framfor det finitte verbet.',m=>[m[1]+' '+m[2]+' ikkje '+m[3]],'subclause');
  pattern(bounds('eit\\s+(fin|stor|god|liten)\\s+(hus|bilete|rom|barn|smil|døme)'),'grammar','La adjektivet passe til inkjekjønn','Eit er inkjekjønn. Adjektivet får her forma fint, stort, godt eller lite.',m=>['eit '+({fin:'fint',stor:'stort',god:'godt',liten:'lite'}[m[1].toLowerCase()])+' '+m[2]],'neuter');
  pattern(bounds('ei\\s+liten\\s+(jente|bok|stund|gruppe)'),'grammar','Hokjønnsforma er «lita»','Liten blir bøygd liten – lita – lite – små.',m=>['ei lita '+m[1]],'feminine');
  pattern(bounds('(fleire|mange|nokre)\\s+(fin|stor|god)\\s+(bøker|hus|dagar|elevar)'),'grammar','Samsvar i fleirtal','Adjektivet får vanlegvis -e i fleirtal.',m=>[m[1]+' '+({fin:'fine',stor:'store',god:'gode'}[m[2].toLowerCase()])+' '+m[3]],'plural');
  pattern(/(?<![\p{L}\p{M}])([\p{L}\p{M}]+)\s+\1(?![\p{L}\p{M}])/giu,'grammar','Er ordet gjenteke med vilje?','Eit ord står to gonger etter kvarandre. Det kan vere eit uhell, men gjentaking kan òg vere eit verkemiddel.',m=>[m[1]],'repeat');
  pattern(/(?<=\p{L})[ \t]+[,;:!?]/gu,'grammar','Mellomrom før teiknet','Vanlegvis er det ikkje mellomrom før komma, semikolon, kolon, spørjeteikn eller utropsteikn.',m=>[m[0].trim()],'space-before');
  pattern(/([\p{L}]),(?=[\p{L}])/gu,'grammar','Mellomrom etter komma','I vanleg løpande tekst skal det vere eit mellomrom etter komma.',m=>[m[1]+', '],'space-after');
  pattern(bounds('gjorde\\s+ei\\s+vurdering'),'style','La verbet gjere meir av arbeidet','Vurderte uttrykkjer handlinga direkte. Begge uttrykka kan vere rette; vel ut frå sjangeren.',()=>['vurderte'],'nominal-past');
  pattern(bounds('gjer\\s+ei\\s+vurdering'),'style','Eit kortare handlingsverb','Vurderer kan vere meir direkte enn gjer ei vurdering.',()=>['vurderer'],'nominal-present');
  pattern(bounds('gjere\\s+ei\\s+vurdering'),'style','Prøv eit direkte verb','Vurdere kan gjere formuleringa kortare.',()=>['vurdere'],'nominal-inf');
  pattern(bounds('på\\s+grunn\\s+av\\s+det\\s+faktum\\s+at'),'style','Kan du seie det kortare?','Fordi kan uttrykkje den same årsakssamanhengen meir direkte.',()=>['fordi'],'because');
  pattern(bounds('i\\s+forhold\\s+til'),'style','Kva samanheng meiner du?','Uttrykket passar ved samanlikning. Dersom du meiner om, for, når det gjeld eller samanlikna med, kan det vere meir presist å skrive det. Ingen automatisk erstatning blir føreslått.',null,'relation');
  pattern(bounds('(det\\s+vart|det\\s+blei|det\\s+blir)\\s+(bestemt|vedteke|avgjort|sagt|gjort)'),'style','Vil du vise kven som handlar?','Dersom du veit kven som handlar, kan aktiv form gjere setninga tydelegare. Passiv kan passe når aktøren er uviktig eller ukjend. Ikkje legg til opplysningar du ikkje har dekning for.',null,'passive');
  if(genre==='story')pattern(bounds('(veldig|svært)\\s+(redd|glad|trøytt|sint|nervøs)'),'style','Prøv å vise kjensla','I ei forteljing kan handling, lyd eller ein detalj vise kjensla. Kva gjer personen? Den direkte skildringa kan òg passe.',null,'show');
  const sentences=[...text.matchAll(/[^.!?\n]+[.!?]*/gu)].map(m=>({start:m.index,end:m.index+m[0].length,text:m[0],tokens:words(m[0])})).filter(s=>s.tokens.length);
  for(const s of sentences){if(s.tokens.length>28)add(s.start,s.end,'style','Ei lang setning å sjå nærare på',`Denne setninga har ${s.tokens.length} ord. Kan ho delast utan at samanhengen blir borte? Lengd åleine er ikkje ein feil.`,[],'long-sentence')}
  for(let i=2;i<sentences.length;i++){const a=sentences[i-2],b=sentences[i-1],c=sentences[i];const first=s=>s.tokens[0][0].toLowerCase();if(first(a)===first(b)&&first(b)===first(c))add(c.start+c.tokens[0].index,c.start+c.tokens[0].index+c.tokens[0][0].length,'style','Tre setningar startar likt','Vurder variasjon med eit tidsuttrykk eller eit anna setningsledd. Gjentaking kan òg vere eit medvite verkemiddel.',[],'same-start')}
  const priority={norm:0,grammar:1,style:2};issues.sort((a,b)=>priority[a.category]-priority[b.category]||a.start-b.start||a.end-b.end);
  return {issues,quotes,metrics:{words:tokens.length,sentences:sentences.length,paragraphs:text.trim()?text.trim().split(/\n\s*\n/).length:0,average:sentences.length?Math.round(tokens.length/sentences.length):0,longest:Math.max(0,...sentences.map(s=>s.tokens.length))},genre};
 }
 function apply(text,issue,replacement){if(text.slice(issue.start,issue.end)!==issue.original)throw Error('Teksten er endra. Analyser på nytt.');if(!issue.replacements.includes(replacement))throw Error('Ukjent forslag.');return text.slice(0,issue.start)+replacement+text.slice(issue.end)}
 return {analyze,apply,quoteRanges,matchCase};
})();
if(typeof module!=='undefined'&&module.exports)module.exports=WritingEngine;
